// Package gomod generates go.mod / go.sum from bob's declarations, computes Go's h1: hashes
// itself (no golang.org/x/mod dependency), and detects hand edits (drift).
package gomod

import (
	"archive/zip"
	"bytes"
	"crypto/sha256"
	"encoding/base64"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// Header marks bob-generated files. go.mod allows // comments; the go command keeps them.
const Header = "// Code generated by bob from bob.go. DO NOT EDIT.\n// Add, remove or upgrade Go modules in bob.go; `go get` and `go mod tidy` are not used with bob.\n"

// Module is one entry of the module graph recorded in bob.lock.
type Module struct {
	Path     string `json:"path"`
	Version  string `json:"version"`
	ZipHash  string `json:"zip,omitempty"`   // SRI sha256 of the proxy zip (fixed-output fetch), only if packages are used
	H1       string `json:"h1,omitempty"`    // go.sum hash of the module tree (only if packages are used)
	ModH1    string `json:"modH1"`           // go.sum hash of the module's go.mod
	Go       string `json:"go,omitempty"`    // `go` directive of the module
	Direct   bool   `json:"direct"`          // imported by workspace packages (else // indirect)
	Packages bool   `json:"packages"`        // provides packages to the build (else only in the module graph)
}

// GoMod renders the go.mod for a workspace module. requires: modules that provide packages.
func GoMod(modPath, goVersion string, mods []Module) string {
	var b strings.Builder
	b.WriteString(Header)
	fmt.Fprintf(&b, "\nmodule %s\n\ngo %s\n", modPath, canonGo(goVersion))
	var direct, indirect []Module
	for _, m := range mods {
		if !m.Packages {
			continue
		}
		if m.Direct {
			direct = append(direct, m)
		} else {
			indirect = append(indirect, m)
		}
	}
	for _, blk := range [][]Module{direct, indirect} {
		if len(blk) == 0 {
			continue
		}
		sort.Slice(blk, func(i, j int) bool { return blk[i].Path < blk[j].Path })
		b.WriteString("\nrequire (\n")
		for _, m := range blk {
			fmt.Fprintf(&b, "\t%s %s", m.Path, m.Version)
			if !m.Direct {
				b.WriteString(" // indirect")
			}
			b.WriteString("\n")
		}
		b.WriteString(")\n")
	}
	return b.String()
}

// canonGo writes the go directive the way current go commands do (1.26 -> 1.26.0), so that a
// go command touching the file does not by itself create drift.
func canonGo(v string) string {
	if strings.Count(v, ".") == 1 {
		return v + ".0"
	}
	return v
}

// GoSum renders go.sum: tree hashes for package-providing modules, go.mod hashes for all
// modules of the (pruned) module graph. Sorted like cmd/go.
func GoSum(mods []Module) string {
	var lines []string
	for _, m := range mods {
		if m.Packages && m.H1 != "" {
			lines = append(lines, fmt.Sprintf("%s %s %s", m.Path, m.Version, m.H1))
		}
		lines = append(lines, fmt.Sprintf("%s %s/go.mod %s", m.Path, m.Version, m.ModH1))
	}
	sort.Strings(lines)
	return strings.Join(lines, "\n") + "\n"
}

// Hash1 is Go's "h1:" hash (dirhash.Hash1): sha256 over "sha256hex  name\n" lines, names sorted.
func Hash1(names []string, open func(string) (io.ReadCloser, error)) (string, error) {
	h := sha256.New()
	names = append([]string(nil), names...)
	sort.Strings(names)
	for _, n := range names {
		if strings.Contains(n, "\n") {
			return "", fmt.Errorf("file name with newline: %q", n)
		}
		r, err := open(n)
		if err != nil {
			return "", err
		}
		fh := sha256.New()
		_, err = io.Copy(fh, r)
		r.Close()
		if err != nil {
			return "", err
		}
		fmt.Fprintf(h, "%x  %s\n", fh.Sum(nil), n)
	}
	return "h1:" + base64.StdEncoding.EncodeToString(h.Sum(nil)), nil
}

// HashZip computes the h1: of a module zip (as go.sum's first line per module).
func HashZip(path string) (string, error) {
	z, err := zip.OpenReader(path)
	if err != nil {
		return "", err
	}
	defer z.Close()
	files := map[string]*zip.File{}
	var names []string
	for _, f := range z.File {
		if strings.HasSuffix(f.Name, "/") {
			continue
		}
		files[f.Name] = f
		names = append(names, f.Name)
	}
	return Hash1(names, func(n string) (io.ReadCloser, error) { return files[n].Open() })
}

// HashMod computes the h1: of a go.mod file's content (go.sum's "/go.mod" line).
func HashMod(data []byte) (string, error) {
	return Hash1([]string{"go.mod"}, func(string) (io.ReadCloser, error) { return io.NopCloser(bytes.NewReader(data)), nil })
}

// ZipGoMod extracts path@version/go.mod from a module zip ("module <path>\n" if absent, as cmd/go).
func ZipGoMod(zipPath, modPath, version string) ([]byte, error) {
	z, err := zip.OpenReader(zipPath)
	if err != nil {
		return nil, err
	}
	defer z.Close()
	for _, f := range z.File {
		if f.Name == modPath+"@"+version+"/go.mod" {
			r, err := f.Open()
			if err != nil {
				return nil, err
			}
			defer r.Close()
			return io.ReadAll(r)
		}
	}
	return []byte("module " + modPath + "\n"), nil
}

// Drift compares the files on disk with what bob would generate. It returns nil if they match
// or do not exist yet (first generation).
func Drift(dir string, want map[string]string) error {
	var problems []string
	for _, name := range sortedKeys(want) {
		have, err := os.ReadFile(filepath.Join(dir, name))
		if os.IsNotExist(err) {
			continue
		}
		if err != nil {
			return err
		}
		if string(have) == want[name] {
			continue
		}
		problems = append(problems, explain(name, string(have), want[name])...)
	}
	if len(problems) == 0 {
		return nil
	}
	return &DriftError{Dir: dir, Lines: problems}
}

type DriftError struct {
	Dir   string
	Lines []string
}

func (e *DriftError) Error() string {
	return fmt.Sprintf("✗ %s/go.mod or go.sum was changed outside bob (they are generated from bob.go)\n%s\n"+
		"  hint: declare Go modules in bob.go (e.g. go.Require(\"golang.org/x/text\", \"v0.20.0\")) and run `bob lock`;\n"+
		"        `go get` and `go mod tidy` are not used with bob. To discard the edit: bob gen --force",
		e.Dir, strings.Join(e.Lines, "\n"))
}

type req struct{ ver, note string }

// parseRequires is a small go.mod reader for diagnostics only (not for building).
func parseRequires(s string) (goVer string, reqs map[string]req) {
	reqs = map[string]req{}
	in := false
	for _, l := range strings.Split(s, "\n") {
		t := strings.TrimSpace(l)
		note := ""
		if i := strings.Index(t, "//"); i >= 0 {
			note = strings.TrimSpace(t[i+2:])
			t = strings.TrimSpace(t[:i])
		}
		f := strings.Fields(t)
		switch {
		case len(f) == 2 && f[0] == "go":
			goVer = f[1]
		case len(f) >= 2 && f[0] == "require" && f[1] == "(":
			in = true
		case len(f) == 3 && f[0] == "require":
			reqs[f[1]] = req{f[2], note}
		case in && len(f) == 1 && f[0] == ")":
			in = false
		case in && len(f) == 2:
			reqs[f[0]] = req{f[1], note}
		}
	}
	return
}

func explain(name, have, want string) []string {
	if name != "go.mod" {
		return []string{fmt.Sprintf("    %s differs from the hashes in bob.lock", name)}
	}
	var out []string
	hg, hr := parseRequires(have)
	wg, wr := parseRequires(want)
	if hg != wg {
		out = append(out, fmt.Sprintf("    ~ go %s → %s (set GoVersion in bob.go)", wg, hg))
	}
	for _, p := range sortedKeys(hr) {
		w, ok := wr[p]
		switch {
		case !ok:
			out = append(out, fmt.Sprintf("    + %s %s  (not declared in bob.go)", p, hr[p].ver))
		case w.ver != hr[p].ver:
			out = append(out, fmt.Sprintf("    ~ %s %s → %s  (bob.go declares %s)", p, w.ver, hr[p].ver, w.ver))
		}
	}
	for _, p := range sortedKeys(wr) {
		if _, ok := hr[p]; !ok {
			out = append(out, fmt.Sprintf("    - %s %s  (declared in bob.go, removed from go.mod)", p, wr[p].ver))
		}
	}
	if len(out) == 0 {
		out = append(out, "    (formatting or comments changed)")
	}
	return out
}

func sortedKeys[V any](m map[string]V) []string {
	ks := make([]string, 0, len(m))
	for k := range m {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	return ks
}
